/**
 * CI arm for scripts/skill-preapproval-inventory.mjs (#4542).
 *
 * Two things must hold:
 *   1. The table in doctor/references/skill-preapproval.md matches the skills,
 *      so a skill that starts pre-granting Bash cannot ship unlisted.
 *   2. The classifier follows the tools-reference "Permission required" column:
 *      a known prompt-gated tool is gated, a known free tool is not, and a
 *      specifier (`Bash(git:*)`) does not hide the tool.
 *
 * scripts/ci/run-tests.sh discovers tests/skills by directory, so no roster edit.
 */
import { spawnSync } from 'node:child_process';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import assert from 'node:assert/strict';

const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..', '..');
const SCRIPT = join(REPO_ROOT, 'scripts', 'skill-preapproval-inventory.mjs');
const { isPromptGated, parseAllowedTools } = await import(SCRIPT);

for (const t of ['Bash', 'Write', 'Edit', 'WebFetch', 'WebSearch', 'Skill', 'Monitor', 'Workflow', 'Bash(git:*)', 'mcp__memory__search_nodes']) {
  assert.equal(isPromptGated(t), true, `${t} prompts in manual mode and must count`);
}
for (const t of ['Read', 'Grep', 'Glob', 'Agent', 'AskUserQuestion', 'TaskCreate', 'ToolSearch', 'SendMessage', 'CronCreate', 'ExitWorktree', 'PushNotification']) {
  assert.equal(isPromptGated(t), false, `${t} never prompts and must not count`);
}
assert.deepEqual(parseAllowedTools('---\nname: x\nallowed-tools: [Read, Bash]\n---\n'), ['Read', 'Bash']);
assert.deepEqual(parseAllowedTools('---\nname: x\nallowed-tools:\n  - Read\n  - Write\nskills: []\n---\n'), ['Read', 'Write']);
assert.equal(parseAllowedTools('---\nname: x\n---\n'), null);
console.log('PASS: classifier and parser');

const result = spawnSync(process.execPath, [SCRIPT], { stdio: 'inherit', cwd: REPO_ROOT });
process.exit(result.status ?? 1);
